type SunburstView = 'burst' | 'donut';

// Per-user (not per-tournament) preference for the overview chart toggle.
const SUNBURST_VIEW_KEY = 'tmx:overview:sunburstView';
const SUNBURST_VIEW_DEFAULT: SunburstView = 'donut';

function readSunburstView(): SunburstView {
  try {
    const stored = localStorage.getItem(SUNBURST_VIEW_KEY);
    return stored === 'burst' || stored === 'donut' ? stored : SUNBURST_VIEW_DEFAULT;
  } catch {
    return SUNBURST_VIEW_DEFAULT;
  }
}

function writeSunburstView(view: SunburstView): void {
  try {
    localStorage.setItem(SUNBURST_VIEW_KEY, view);
  } catch {
    // storage unavailable
  }
}

// Burst coloring: 'progression' = seed/entry coloring; 'competitive' = winner
// rings colored by matchUp competitiveness. Per-user preference, only relevant
// while the burst (not donut) view is shown.
type BurstColor = 'progression' | 'competitive';

const BURST_COLOR_KEY = 'tmx:overview:burstColor';
const BURST_COLOR_DEFAULT: BurstColor = 'progression';

function readBurstColor(): BurstColor {
  try {
    const stored = localStorage.getItem(BURST_COLOR_KEY);
    return stored === 'progression' || stored === 'competitive' ? stored : BURST_COLOR_DEFAULT;
  } catch {
    return BURST_COLOR_DEFAULT;
  }
}

function writeBurstColor(color: BurstColor): void {
  try {
    localStorage.setItem(BURST_COLOR_KEY, color);
  } catch {
    // storage unavailable
  }
}

const ALL_STRUCTURES = 'all';

export function createSunburstPanel(structures: StructureInfo[]): HTMLElement {
  const panel = document.createElement('div');
  panel.className = 'dash-panel dash-panel-green';

  let view: SunburstView = readSunburstView();
  let burstColor: BurstColor = readBurstColor();
  let burstInstance: { setColorMode: (m: 'default' | 'competitiveness') => void } | undefined;
  const burstColorOption = (): 'default' | 'competitiveness' =>
    burstColor === 'competitive' ? 'competitiveness' : 'default';

  // Header row: structure dropdown + view toggle
  const header = document.createElement('div');
  header.style.cssText = 'display:flex; align-items:center; gap:8px; margin-bottom:12px;';

  const select = document.createElement('select');
  select.style.cssText =
    'flex:1; min-width:0; padding:4px 8px; border-radius:4px; border:1px solid var(--tmx-border-primary); background:var(--tmx-bg-primary); color:var(--tmx-text-primary);';

  const allOption = document.createElement('option');
  allOption.value = ALL_STRUCTURES;
  allOption.textContent = t('dashboard.allStructures');
  select.appendChild(allOption);

  for (const s of structures) {
    const option = document.createElement('option');
    option.value = s.structureId;
    option.textContent = `${s.eventName} — ${s.drawName} — ${s.structureName}`;
    select.appendChild(option);
  }
  header.appendChild(select);

  const toggleBtn = document.createElement('button');
  toggleBtn.style.cssText = ICON_BTN_STYLE;
  const setToggleAppearance = () => {
    const showingBurst = view === 'burst';
    toggleBtn.innerHTML = `<i class="fa ${showingBurst ? 'fa-chart-pie' : 'fa-circle-notch'}"></i>`;
    toggleBtn.title = showingBurst ? t('dashboard.viewCompetitiveness') : t('dashboard.viewBracket');
  };
  setToggleAppearance();
  header.appendChild(toggleBtn);

  const setToggleVisibility = (visible: boolean) => {
    toggleBtn.style.display = visible ? '' : 'none';
  };

  // Burst color toggle (progression ↔ competitive) — only shown in burst view.
  const colorToggleBtn = document.createElement('button');
  colorToggleBtn.style.cssText = ICON_BTN_STYLE;
  const setColorToggleAppearance = () => {
    const competitive = burstColor === 'competitive';
    colorToggleBtn.innerHTML = `<i class="fa ${competitive ? 'fa-fire' : 'fa-seedling'}"></i>`;
    colorToggleBtn.title = competitive
      ? t('dashboard.burstColorCompetitive', { defaultValue: 'Coloring: competitiveness — click for progression' })
      : t('dashboard.burstColorProgression', { defaultValue: 'Coloring: progression — click for competitiveness' });
  };
  setColorToggleAppearance();
  header.appendChild(colorToggleBtn);

  const setColorToggleVisibility = (visible: boolean) => {
    colorToggleBtn.style.display = visible ? '' : 'none';
  };

  panel.appendChild(header);

  const chartDiv = document.createElement('div');
  chartDiv.style.cssText = 'display:flex; justify-content:center;';
  panel.appendChild(chartDiv);

  const renderBurst = (info: StructureInfo) => {
    const eventData = tournamentEngine.q.eventData({ eventId: info.eventId });
    const drawData = eventData?.drawsData
      ?.find((d: any) => d.drawId === info.drawId)
      ?.structures?.find((s: any) => s.structureId === info.structureId);
    if (!drawData) return;

    chartDiv.innerHTML = '';
    const title = `${info.eventName}\n${info.drawName}`;
    const eventHandlers = {
      clickSegment: (data: any) => {
        const matchUp = data?.matchUp;
        if (matchUp?.readyToScore || matchUp?.scoreString) {
          enterMatchUpScore({ matchUpId: matchUp.matchUpId, callback: () => renderStructure(select.value) });
        }
      },
      clickCenter: () => {
        navigateToEvent({
          eventId: info.eventId,
          drawId: info.drawId,
          structureId: info.structureId,
          renderDraw: true,
        });
      },
    };
    burstInstance = burstChart({ width: 500, height: 500, colorMode: burstColorOption(), eventHandlers }).render(
      chartDiv,
      fromFactoryDrawData(drawData),
      title,
    );
  };

  const renderDonut = (info: StructureInfo | null) => {
    const matchUpFilters = info ? { drawIds: [info.drawId], structureIds: [info.structureId] } : undefined;
    const { matchUps = [] } = tournamentEngine.allTournamentMatchUps({
      contextProfile: { withCompetitiveness: true },
      inContext: false,
      matchUpFilters,
    });

    chartDiv.innerHTML = '';
    const title = info ? `${info.eventName} — ${info.drawName}` : t('dashboard.allStructures');
    donutChartFromMatchUps(chartDiv, matchUps, { width: 500, height: 500, title });
  };

  const renderStructure = (value: string) => {
    if (value === ALL_STRUCTURES) {
      setToggleVisibility(false);
      setColorToggleVisibility(false);
      renderDonut(null);
      return;
    }
    const info = structures.find((s) => s.structureId === value);
    if (!info) return;
    setToggleVisibility(true);
    if (view === 'donut') {
      setColorToggleVisibility(false);
      renderDonut(info);
    } else {
      setColorToggleVisibility(true);
      renderBurst(info);
    }
  };

  toggleBtn.addEventListener('click', () => {
    view = view === 'burst' ? 'donut' : 'burst';
    writeSunburstView(view);
    setToggleAppearance();
    renderStructure(select.value);
  });

  colorToggleBtn.addEventListener('click', () => {
    burstColor = burstColor === 'competitive' ? 'progression' : 'competitive';
    writeBurstColor(burstColor);
    setColorToggleAppearance();
    // Instant recolor without rebuilding the chart.
    burstInstance?.setColorMode(burstColorOption());
  });

  select.addEventListener('change', () => renderStructure(select.value));

  select.value = ALL_STRUCTURES;
  requestAnimationFrame(() => renderStructure(ALL_STRUCTURES));

  return panel;
}

function changeOnlineState({
  postMutation,
  state,
  offline,
}: {
  postMutation?: (result: any) => void;
  state: any;
  offline: boolean;
}): void {
  const itemValue = { ...tournamentEngine.q.tournamentTimeItem({ itemType: 'TMX' })?.itemValue };
  if (offline) {
    itemValue.offline = { email: state.email };
  } else {
    delete itemValue.offline;
  }
  const timeItem = { itemType: 'TMX', itemValue };
  mutationRequest({
    methods: [{ method: ADD_TOURNAMENT_TIMEITEM, params: { removePriorValues: true, timeItem } }],
    callback: postMutation,
  });
}

/**
 * Re-mark the tournament offline in THIS tab only, after a go-online save that did not land. The
 * offline flag was cleared to send the copy, so a `changeOnlineState` here would run server-first and
 * write this copy's TMX time item over the server's record, which on a conflict is someone else's
 * newer one. Local engine and IndexedDB only; repeating go-online reuses the save's commandId.
 */
function restoreOfflineLocally(state: any): void {
  const prior = tournamentEngine.q.tournamentTimeItem({ itemType: 'TMX' })?.itemValue;
  const itemValue = { ...prior, offline: { email: state.email } };
  tournamentEngine.addTournamentTimeItem({ removePriorValues: true, timeItem: { itemType: 'TMX', itemValue } });
  saveTournamentRecord();
}

function createActionButton(label: string, icon: string, onClick: () => void, id?: string): HTMLElement {
  const btn = document.createElement('button');
  btn.className = 'dash-action-btn';
  if (id) btn.id = id;
  btn.innerHTML = `<i class="fa ${icon}"></i> ${label}`;
  btn.addEventListener('click', onClick);
  return btn;
}

// The format wizard is most useful early in tournament setup —
// before flighting / event-entry decisions have been made. Show
// the launch button when there are no events at all, or when
// participants exist but no event has been populated with entries
// yet.
/**
 * @param participants optional pre-fetched participants list to skip the
 *   internal `getParticipants` call.
 * @param events optional pre-fetched events list to skip the internal
 *   `getEvents` call. The overview render shares both with the dashboard
 *   data + scalings panel paths so a single render only fans out one
 *   getParticipants and zero extra getEvents calls for this check.
 */
export function shouldShowFormatWizard(participants?: any[], events?: any[]): boolean {
  if (!featureFlags.get().formatWizard) return false;
  const eventList = events ?? (tournamentEngine.getEvents?.() as any)?.events ?? [];
  if (eventList.length === 0) return true;
  const list = participants ?? (tournamentEngine.getParticipants?.({}) as any)?.participants ?? [];
  if (list.length === 0) return false;
  const totalEntries = eventList.reduce((sum: number, e: any) => sum + ((e?.entries as any[])?.length ?? 0), 0);
  return totalEntries === 0;
}

function navigateToFormatWizard(): void {
  const tournamentId = tournamentEngine.q.tournament()?.tournamentId;
  if (!tournamentId) return;
  context.router?.navigate(`/${TOURNAMENT}/${tournamentId}/format-wizard`);
}

export function createActionsPanel(): HTMLElement {
  const panel = document.createElement('div');
  panel.className = 'dash-panel dash-panel-red';

  const header = document.createElement('div');
  header.style.cssText =
    'font-size:1rem; font-weight:600; display:flex; align-items:center; gap:8px; margin-bottom:12px;';
  const headerIcon = document.createElement('i');
  headerIcon.className = 'fa fa-bolt';
  headerIcon.style.fontSize = '0.9rem';
  header.appendChild(headerIcon);
  header.appendChild(document.createTextNode(t('loginMenu.actions')));
  panel.appendChild(header);

  const btnContainer = document.createElement('div');
  btnContainer.className = 'dash-action-buttons';
  panel.appendChild(btnContainer);

  const tournamentRecord = tournamentEngine.q.tournament();
  const offline = tournamentRecord?.timeItems?.find(({ itemType }: any) => itemType === 'TMX')?.itemValue?.offline;
  const provider = tournamentRecord?.parentOrganisation;
  const providerId = provider?.organisationId;
  const state = getLoginState();
  const admin = isActiveProviderAdmin();
  const activeProvider = resolveActiveProvider(state, context.provider);

  if (tournamentRecord && admin) {
    if (shouldShowFormatWizard()) {
      btnContainer.appendChild(
        createActionButton(
          t('formatWizard.title'),
          'fa-magic',
          () => navigateToFormatWizard(),
          FORMAT_WIZARD_ACTION_BUTTON,
        ),
      );
    }
    btnContainer.appendChild(
      createActionButton(t('modals.tournamentActions.exportUtr'), 'fa-download', () => downloadUTRmatches()),
    );
    btnContainer.appendChild(
      createActionButton(t('modals.tournamentActions.exportCodes'), 'fa-download', () => {
        downloadJSON(`${tournamentRecord.tournamentId}.codes.json`, tournamentRecord);
      }),
    );
  }

  // Manage access itself lives in the admin console (provider admin work belongs
  // there, not in TMX which is end-user-only). What is here is a DEEP LINK, not
  // a return of that UI: grants are per-tournament, and this panel is the only
  // place in TMX that already knows which tournament — the avatar menu does not,
  // which is why the general console icon in homeNavigation cannot serve this.
  if (tournamentRecord && admin && providerId) {
    btnContainer.appendChild(
      createActionButton(t('modals.tournamentActions.scopedAccess'), 'fa-user-shield', () => {
        const route = consoleGrantsRoute(tournamentRecord.tournamentId);
        globalThis.open(consoleUrl(globalThis.location.origin, route), '_blank', 'noopener');
      }),
    );
  }

  if (providerId) {
    btnContainer.appendChild(
      createActionButton(t('modals.tournamentActions.uploadTournament'), 'fa-upload', () => {
        const record = tournamentEngine.q.tournament();
        openModal({
          title: t('modals.tournamentActions.uploadTournament'),
          content: t('modals.tournamentActions.uploadWarning'),
          buttons: [
            { label: t('common.cancel'), close: true },
            {
              label: t('common.send'),
              intent: 'is-danger',
              close: true,
              onClick: () => {
                if (!record) return;
                durableSave({ tournamentRecord: record, flow: 'upload', send: sendTournament }).then((result) => {
                  if (result.status === 'saved') return success();
                  reportSaveOutcome(result, 'upload', record.tournamentId);
                }, failure);
              },
            },
          ],
        });
      }),
    );
  }

  // A demo tournament carries simulated clock times (demoClock): never claim it into a provider's records.
  if (tournamentRecord && !providerId && activeProvider && !hasSchedulingDemoScript(tournamentRecord)) {
    btnContainer.appendChild(
      createActionButton(t('modals.tournamentActions.claimTournament'), 'fa-hand-paper', () => {
        const record = tournamentEngine.q.tournament();
        if (record && !record.parentOrganisation) {
          record.parentOrganisation = activeProvider;
          tournamentEngine.setState(record);
          durableSave({ tournamentRecord: record, flow: 'claim', send: sendTournament }).then(
            (result) => {
              if (result.status !== 'saved') {
                // Not claimed (or not known to be): back to the unclaimed copy, which is what
                // IndexedDB still holds, so the claim can be repeated. An unchanged repeat of an
                // uncertain claim reuses its commandId, and the server answers whether it landed.
                delete record.parentOrganisation;
                tournamentEngine.setState(record);
                reportSaveOutcome(result, 'claim', record.tournamentId);
                return;
              }
              tmx2db.deleteTournament(record.tournamentId);
              tmxToast({ message: t('modals.tournamentActions.tournamentClaimed'), intent: 'is-info' });
              renderOverview();
            },
            (error: any) => {
              tmxToast({ message: error.message || t('modals.tournamentActions.notClaimed'), intent: 'is-danger' });
            },
          );
        }
      }),
    );
  }

  if (providerId && !offline) {
    btnContainer.appendChild(
      createActionButton(t('modals.tournamentActions.goOffline'), 'fa-wifi', () => {
        changeOnlineState({
          state,
          offline: true,
          postMutation: (result: any) => {
            if (result?.success) {
              saveTournamentRecord();
              // The write it went offline at: going online sends it as the precondition (C3).
              if (tournamentRecord) rememberOfflineSyncPoint(tournamentRecord.tournamentId);
              const dnav = document.getElementById('dnav');
              if (dnav) dnav.style.backgroundColor = 'var(--tmx-bg-highlight)';
              tmxToast({ message: t('modals.tournamentActions.offline'), intent: 'is-info' });
              renderOverview();
            }
          },
        });
      }),
    );
  }

  if (providerId && offline) {
    btnContainer.appendChild(
      createActionButton(t('modals.tournamentActions.goOnline'), 'fa-wifi', () => {
        changeOnlineState({
          state,
          offline: false,
          postMutation: (result: any) => {
            if (result?.success) {
              const updated = tournamentEngine.q.tournament();
              if (!updated) return;
              durableSave({ tournamentRecord: updated, flow: 'goOnline', send: sendTournament }).then(
                (result) => {
                  // Only a save known to have landed (or a deduplicated resend of it) may delete the
                  // offline copy. A conflict, a refusal or an unknown outcome keeps it, offline.
                  if (result.status !== 'saved') {
                    restoreOfflineLocally(state);
                    reportSaveOutcome(result, 'goOnline', updated.tournamentId);
                    return;
                  }
                  forgetOfflineSyncPoint(updated.tournamentId);
                  tmx2db.deleteTournament(updated.tournamentId);
                  const dnav = document.getElementById('dnav');
                  if (dnav) dnav.style.backgroundColor = '';
                  tmxToast({ message: t('modals.tournamentActions.online'), intent: 'is-info' });
                  renderOverview();
                },
                (err: any) => {
                  console.log({ err });
                  restoreOfflineLocally(state);
                },
              );
            }
          },
        });
      }),
    );
  }

  if (!btnContainer.children.length) {
    const noActions = document.createElement('div');
    noActions.style.cssText = 'font-size:0.85rem; color:var(--tmx-text-secondary); font-style:italic;';
    noActions.textContent = t('modals.tournamentActions.noActions');
    btnContainer.appendChild(noActions);
  }

  return panel;
}
