/** The Options panel (last of the preferences row), so a layout check can name it. */
export const OPTIONS_PANEL_ID = 'optionsPanel';

/**
 * Mode (light / dark / system) and the palette for each mode. A user keeps one light and one dark palette, like
 * a language choice; the mode decides which shows. Palette names are proper names and are not translated.
 */
function buildThemePanel(): HTMLElement {
  const panel = document.createElement('div');
  panel.className = SETTINGS_PANEL;
  panel.innerHTML = `<h3><i class="fa-solid fa-palette"></i> ${t('modals.settings.theme')}</h3>`;

  const currentMode = getThemePreference();
  const modeForm = document.createElement('div');
  renderForm(modeForm, [
    {
      label: t('modals.settings.themeMode'),
      options: (['light', 'dark', 'system'] as const).map((mode) => ({
        value: mode,
        label: t(`modals.settings.theme${mode[0].toUpperCase()}${mode.slice(1)}`),
        selected: mode === currentMode,
      })),
      onChange: (e: Event) => applyTheme((e.target as HTMLSelectElement).value as 'light' | 'dark' | 'system'),
      field: 'themeMode',
      id: 'themeMode',
    },
  ]);
  panel.appendChild(modeForm);

  for (const mode of ['light', 'dark'] as ThemeMode[]) {
    const current = getPalettePreference(mode);
    const form = document.createElement('div');
    form.style.marginTop = '8px';
    renderForm(form, [
      {
        label: t(mode === 'dark' ? 'modals.settings.darkPalette' : 'modals.settings.lightPalette'),
        options: getThemePalettes(mode).map(({ id, name }) => ({ value: id, label: name, selected: id === current })),
        onChange: (e: Event) => setPalettePreference(mode, (e.target as HTMLSelectElement).value),
        field: `${mode}Palette`,
        id: `${mode}Palette`,
      },
    ]);
    panel.appendChild(form);
  }

  return panel;
}

const { ratingsParameters } = fixtures;
const { SINGLES } = factoryConstants.eventConstants;

const SETTINGS_PANEL = 'settings-panel';

async function persistAll(
  availableLanguages: string[],
  languageInputs: any,
  ratingInputs: any,
  optionsInputs: any,
  displayInputs: any,
): Promise<void> {
  const activeScale = ratingInputs?.activeRating?.value;
  serverConfig.set({ saveLocal: optionsInputs.saveLocal.checked });
  featureFlags.set({
    formatWizard: displayInputs.formatWizard?.checked || false,
    schedulePlan: displayInputs.schedulePlan?.checked || false,
    linkedTournaments: displayInputs.linkedTournaments?.checked || false,
  });

  // `scoringApproach` is no longer set here: score entry offers its own approach switcher and writes the
  // preference itself (scoreMatchUp.ts), so a stored choice survives saving any other setting.
  preferencesConfig.set({
    // A preference, not a feature flag: the board is finished, this is only
    // whether it is offered. Hence Options rather than Beta features.
    officialsBoard: optionsInputs.officialsBoard?.checked || false,
  });

  const language = languageInputs.language.value;
  // Compare against the code the control was OPENED on, not `i18next.language` — those differ
  // whenever the active language is region-tagged (`en-US` resolving to the `en` option), and
  // comparing raw would report a change on every save and reload the app each time.
  const languageChanged = language !== resolveCurrentLanguageCode(availableLanguages, i18next.language);

  if (activeScale) setActiveScale(activeScale);

  // `languageExplicit` defeats the provider default on every subsequent boot, so it may only be set
  // when the user actually chose a language here. Writing it unconditionally is what turned "changed
  // an unrelated setting" into a permanent, silent switch to whichever option the control happened
  // to be showing. An explicit choice made earlier is preserved.
  const languageExplicit = languageChanged || !!loadSettings()?.languageExplicit;
  persistConfigToStorage({ language, languageExplicit });

  if (languageChanged) {
    // Fetch + cache the new locale BEFORE reload so the post-reload boot
    // can sync-load it from cache via initialState.ts. Without this, the
    // first reload after picking a new language renders English fallbacks
    // until ensureLocaleCurrent's background fetch completes.
    try {
      await ensureLocaleCurrent(language);
    } catch {
      // Fetch failure — proceed with reload anyway; the boot path will
      // retry the fetch and the user gets English fallback in the
      // meantime. Better than blocking the reload indefinitely.
    }
  }

  if (languageChanged) {
    globalThis.location.reload();
  }
}

export async function renderSettingsGrid(
  container: HTMLElement,
  options?: { excludeTournament?: boolean },
): Promise<void> {
  // These are populated after renderForm calls; persist closure captures the refs.
  let languageInputs: any;
  let ratingInputs: any;
  let optionsInputs: any;
  let displayInputs: any;

  let availableLanguages: string[] = [];
  const persist = () => persistAll(availableLanguages, languageInputs, ratingInputs, optionsInputs, displayInputs);

  const grid = document.createElement('div');
  grid.className = 'settings-grid';

  // Panels are built into this map and placed by `getSettingsLayout` at the end, so which panels appear,
  // in which row and how wide, is decided in one pure (tested) place rather than by build order.
  const panels = new Map<SettingsPanelId, HTMLElement>();
  const loggedIn = !!getLoginState();

  // --- Linked tournaments (full width) — first row of the grid, added and removed in place ---
  // Tournament-scoped, and provider-authenticated (it fetches /provider/my-calendars),
  // so it stays hidden when logged out: the panel would 401 and baseApi's interceptor
  // turns a 401 into a full logout, which was breaking the settings tab entirely.
  // getUserContext() is a SYNCHRONOUS read of a cache that only `/auth/me` fills, so it
  // returns undefined until that request resolves — and `fetchUserContext()` is called
  // fire-and-forget at login/boot. This value is then captured by the syncLinkedPanel
  // closure, so a context arriving later never un-sticks it: the panel stays unavailable
  // for the life of the render and the beta checkbox appears to do nothing.
  //
  // getLoginState() answers the same question — is there an authenticated user — by
  // validating the JWT locally. Synchronous, no network, no race. Deliberately NOT
  // `await ensureUserContext()`: that would fire /auth/me for logged-out users, and
  // baseApi's interceptor turns a 401 into a FULL LOGOUT, which is the exact cascade
  // #1218/#1370 were fixing.
  const linkedEligible = isLinkedTournamentsEligible({ excludeTournament: options?.excludeTournament, loggedIn });
  const syncLinkedPanel = () => {
    const existing = grid.querySelector(`#${LINKED_TOURNAMENTS_PANEL_ID}`);
    const enabled = linkedEligible && featureFlags.get().linkedTournaments;
    if (enabled && !existing) {
      grid.prepend(buildLinkedTournamentsPanel());
    } else if (!enabled && existing) {
      existing.remove();
    }
  };
  syncLinkedPanel();

  const deleteContext = resolveDeleteContext(options?.excludeTournament);
  const layout = getSettingsLayout({
    excludeTournament: options?.excludeTournament,
    pipelineEligible: isPipelineEligible(tournamentEngine.q.tournament(), loggedIn),
    canDeleteTournament: !!deleteContext,
    isElectron: !!deviceConfig.get().isElectron,
  });
  const inLayout = (id: SettingsPanelId) => layout.some((row) => row.some((panel) => panel.id === id));

  // Tournament-scoped: a seeding policy is attached to the tournamentRecord. Unlike the linked-tournaments
  // panel this needs no authentication — the catalog is local and the mutation is an ordinary one.
  if (inLayout('seedingPolicy')) panels.set('seedingPolicy', buildSeedingPolicyPanel());

  // Exit-propagation options for testing: offered only logged out or on a mock tournament.
  if (inLayout('pipelineFeatures')) panels.set('pipelineFeatures', buildPipelineFeaturesPanel());

  // --- Language panel (blue, 1 col) ---
  // Source the language list from the CFS manifest so newly-added locales
  // (cs, hr, etc.) appear without a TMX rebuild. force:true so a stale
  // localStorage cache can't hide a locale that's already live on CFS.
  // Fall back to whatever i18next has loaded (bundled en + any locale the
  // runtime-loader already pulled this session) if CFS is unreachable.
  const manifest = await fetchManifest({ force: true });
  const knownInI18next = new Set(Object.keys(i18next.options?.resources || {}));
  const languageOptions = buildLanguageOptions(manifest?.locales, knownInI18next, i18next.language);
  availableLanguages = languageOptions.map((option) => option.value);

  const languagePanel = document.createElement('div');
  languagePanel.className = SETTINGS_PANEL;
  languagePanel.innerHTML = `<h3><i class="fa-solid fa-globe"></i> ${t('modals.settings.language')}</h3>`;

  const languageForm = document.createElement('div');
  languageInputs = renderForm(languageForm, [
    {
      options: languageOptions,
      onChange: persist,
      field: 'language',
      id: 'language',
    },
  ]);
  languagePanel.appendChild(languageForm);

  // Active Rating lives below the language selector in the same panel —
  // tournament-specific so the sub-section only renders inside a tournament.
  if (!options?.excludeTournament) {
    const ratingHeader = document.createElement('h3');
    ratingHeader.style.marginTop = '16px';
    ratingHeader.innerHTML = `<i class="fa-solid fa-star"></i> ${t('modals.settings.activeRating')}`;
    languagePanel.appendChild(ratingHeader);

    // Discover which ratings are present in current tournament participants
    const { participants: allParticipants = [] } = tournamentEngine.getParticipants({ withScaleValues: true }) ?? {};
    const presentRatings = new Set<string>();
    for (const p of allParticipants) {
      for (const item of p.ratings?.[SINGLES] || []) {
        presentRatings.add(item.scaleName);
      }
    }

    // Build rating options: tournament ratings first, then all others (excluding deprecated)
    const allRatingKeys = Object.keys(ratingsParameters).filter((key) => !(ratingsParameters as any)[key].deprecated);
    const inTournament = allRatingKeys.filter((key) => presentRatings.has(key));
    const notInTournament = allRatingKeys.filter((key) => !presentRatings.has(key));

    const ratingOptions = [
      ...inTournament.map((key) => ({
        label: `${key} (in tournament)`,
        value: key.toLowerCase(),
        selected: preferencesConfig.get().activeScale === key.toLowerCase(),
      })),
      ...notInTournament.map((key) => ({
        label: key,
        value: key.toLowerCase(),
        selected: preferencesConfig.get().activeScale === key.toLowerCase(),
      })),
    ];

    const ratingForm = document.createElement('div');
    ratingInputs = renderForm(ratingForm, [
      {
        options: ratingOptions,
        onChange: persist,
        field: 'activeRating',
        id: 'activeRating',
      },
    ]);
    languagePanel.appendChild(ratingForm);
  }

  panels.set('language', languagePanel);

  // --- Theme panel: mode, plus one palette per mode ---
  panels.set('theme', buildThemePanel());

  // --- Font panel ---
  const fontPanel = document.createElement('div');
  fontPanel.className = SETTINGS_PANEL;
  fontPanel.innerHTML = `<h3><i class="fa-solid fa-font"></i> ${t('modals.settings.font')}</h3>`;

  const currentFont = getFontPreference();
  const fontForm = document.createElement('div');
  renderForm(fontForm, [
    {
      options: Object.entries(fontOptions()).map(([key, { label }]) => ({
        value: key,
        label,
        selected: key === currentFont,
      })),
      onChange: (e: Event) => {
        const select = e.target as HTMLSelectElement;
        applyFont(select.value);
      },
      field: 'fontFamily',
      id: 'fontFamily',
    },
  ]);
  fontPanel.appendChild(fontForm);

  const currentFontSize = getFontSizePreference();
  const fontSizeForm = document.createElement('div');
  fontSizeForm.style.marginTop = '8px';
  renderForm(fontSizeForm, [
    {
      options: Object.entries(fontSizeOptions()).map(([key, { label }]) => ({
        value: key,
        label,
        selected: key === currentFontSize,
      })),
      onChange: (e: Event) => {
        const select = e.target as HTMLSelectElement;
        applyFontSize(select.value);
      },
      field: 'fontSize',
      id: 'fontSize',
    },
  ]);
  fontPanel.appendChild(fontSizeForm);

  // PDF font — embedded in generated PDFs for Latin-2 / Central-European names
  const currentPdfFont = loadSettings()?.pdfFont ?? PROVIDER_DEFAULT_FONT;
  const pdfFontForm = document.createElement('div');
  pdfFontForm.style.marginTop = '8px';
  renderForm(pdfFontForm, [
    {
      options: [
        {
          value: PROVIDER_DEFAULT_FONT,
          label: t('modals.settings.useProviderDefault', { defaultValue: 'Use provider default' }),
          selected: currentPdfFont === PROVIDER_DEFAULT_FONT,
        },
        ...getCachedFontCatalog().map((font) => ({
          value: font.id,
          label: font.label,
          selected: font.id === currentPdfFont,
        })),
      ],
      onChange: (e: Event) => {
        const select = e.target as HTMLSelectElement;
        saveSettings({ pdfFont: select.value });
        void ensurePdfFontReady();
      },
      field: 'pdfFont',
      id: 'pdfFont',
    },
  ]);
  fontPanel.appendChild(pdfFontForm);

  panels.set('font', fontPanel);

  // --- Beta Features panel ---
  const displayPanel = document.createElement('div');
  displayPanel.className = SETTINGS_PANEL;
  displayPanel.innerHTML = `<h3><i class="fa-solid fa-display"></i> ${t('modals.settings.betaFeatures')}</h3>`;

  const displayForm = document.createElement('div');
  displayInputs = renderForm(displayForm, [
    {
      label: t('formatWizard.title'),
      checked: featureFlags.get().formatWizard || false,
      field: 'formatWizard',
      id: 'formatWizard',
      onChange: persist,
      checkbox: true,
    },
    {
      label: t('settingsGrid.schedulePlan'),
      checked: featureFlags.get().schedulePlan || false,
      field: 'schedulePlan',
      id: 'schedulePlan',
      onChange: persist,
      checkbox: true,
    },
    // Gated on `linkedEligible` — the SAME value the panel uses, deliberately.
    //
    // A previous pass gated the checkbox on `!excludeTournament` alone while the panel
    // required `!excludeTournament && logged-in`. Two gates that can disagree, and they
    // did: logged out inside a tournament the checkbox was still offered and still could
    // not do anything, which is the exact defect that pass set out to remove. One
    // condition, two consumers, so they cannot drift apart again.
    ...(linkedEligible
      ? [
          {
            label: t('modals.settings.linkedTournaments'),
            checked: featureFlags.get().linkedTournaments || false,
            field: 'linkedTournaments',
            id: 'linkedTournaments',
            // persistAll writes the flags synchronously before its first await, so the
            // panel can be added/removed in place rather than forcing a tab re-render.
            onChange: () => {
              void persist();
              syncLinkedPanel();
            },
            checkbox: true,
          },
        ]
      : []),
  ]);

  if (deviceConfig.get().isElectron) {
    const notifRow = document.createElement('div');
    notifRow.style.cssText = 'display:flex;align-items:center;margin-top:8px';
    const notifCheckbox = document.createElement('input');
    notifCheckbox.type = 'checkbox';
    notifCheckbox.id = 'desktopNotifications';
    notifCheckbox.checked = isDesktopNotificationsEnabled();
    notifCheckbox.addEventListener('change', () => setDesktopNotificationsEnabled(notifCheckbox.checked));
    const notifLabel = document.createElement('label');
    notifLabel.htmlFor = 'desktopNotifications';
    notifLabel.textContent = t('settingsGrid.desktopNotifications');
    notifLabel.style.marginLeft = '4px';
    notifRow.appendChild(notifCheckbox);
    notifRow.appendChild(notifLabel);
    displayForm.appendChild(notifRow);
  }
  displayPanel.appendChild(displayForm);
  panels.set('betaFeatures', displayPanel);

  // --- Options panel ---
  // Was "Storage" when it held one saveLocal checkbox. Widened rather than a new
  // panel added, so settings that are neither beta nor storage have a home.
  const optionsPanel = document.createElement('div');
  optionsPanel.className = SETTINGS_PANEL;
  optionsPanel.id = OPTIONS_PANEL_ID;
  optionsPanel.innerHTML = `<h3><i class="fa-solid fa-sliders"></i> ${t('modals.settings.options')}</h3>`;

  const optionsForm = document.createElement('div');
  optionsInputs = renderForm(optionsForm, [
    {
      label: t('modals.settings.saveLocalCopies'),
      checked: serverConfig.get().saveLocal,
      field: 'saveLocal',
      id: 'saveLocal',
      onChange: persist,
      checkbox: true,
    },
    {
      label: t('modals.settings.officialsBoard'),
      checked: preferencesConfig.get().officialsBoard,
      field: 'officialsBoard',
      id: 'officialsBoard',
      // persistAll writes the preference synchronously before its first await, so
      // the nav rail can be re-evaluated straight after rather than on next render.
      onChange: () => {
        void persist();
        applyTabCapabilityVisibility();
      },
      checkbox: true,
    },
  ]);
  optionsPanel.appendChild(optionsForm);
  panels.set('options', optionsPanel);

  // --- Connection panel — Electron only ---
  if (inLayout('connection')) {
    const connectionPanel = document.createElement('div');
    connectionPanel.className = SETTINGS_PANEL;
    connectionPanel.innerHTML = `<h3><i class="fa-solid fa-server"></i> Connection</h3>`;

    const serverUrlLabel = document.createElement('label');
    serverUrlLabel.className = 'label';
    serverUrlLabel.textContent = t('settingsGrid.serverUrl');
    serverUrlLabel.style.marginBottom = '4px';

    const serverUrlInput = document.createElement('input');
    serverUrlInput.className = 'input';
    serverUrlInput.type = 'text';
    serverUrlInput.value = serverConfig.get().socketPath || '';
    serverUrlInput.placeholder = 'http://localhost:8383';

    const statusDot = document.createElement('span');
    const updateStatus = () => {
      const isConnected = connected();
      statusDot.style.cssText = `display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:6px;background:${isConnected ? 'var(--tmx-status-success)' : 'var(--tmx-status-error)'}`;
    };
    updateStatus();

    const statusLabel = document.createElement('span');
    statusLabel.style.fontSize = '0.85rem';
    const updateStatusLabel = () => {
      statusLabel.textContent = connected() ? 'Connected' : 'Disconnected';
    };
    updateStatusLabel();

    const statusRow = document.createElement('div');
    statusRow.style.cssText = 'display:flex;align-items:center;margin-top:8px;margin-bottom:8px';
    statusRow.appendChild(statusDot);
    statusRow.appendChild(statusLabel);

    const offlineCheckbox = document.createElement('input');
    offlineCheckbox.type = 'checkbox';
    offlineCheckbox.id = 'workOffline';
    offlineCheckbox.checked = !serverConfig.get().serverFirst;

    const offlineLabel = document.createElement('label');
    offlineLabel.htmlFor = 'workOffline';
    offlineLabel.textContent = t('settingsGrid.workOffline');
    offlineLabel.style.marginLeft = '4px';

    const offlineRow = document.createElement('div');
    offlineRow.style.cssText = 'display:flex;align-items:center;margin-top:8px';
    offlineRow.appendChild(offlineCheckbox);
    offlineRow.appendChild(offlineLabel);

    // Save server URL on blur — but only once it is confirmed. Main validates the URL and asks the user in
    // a native dialog; applying it here first meant a declined (or invalid) URL still steered this
    // session's socket and REST until the next reload.
    let confirmedServerUrl = serverUrlInput.value.trim();
    serverUrlInput.addEventListener('change', async () => {
      const url = serverUrlInput.value.trim();
      if (platform.setServerUrl) {
        const { saved } = await platform.setServerUrl(url);
        if (!saved) {
          serverUrlInput.value = confirmedServerUrl;
          return;
        }
      }
      confirmedServerUrl = url;
      serverConfig.set({ socketPath: url });
      // Re-point the REST layer too. `serverConfig.socketPath` only steers
      // Socket.IO; without this the axios instance keeps the base URL it
      // captured at module load, so changing the server here moved the socket
      // to the new host while every REST call kept going to the old one (in a
      // packaged app, to `file://`) until the app was restarted.
      setBaseURL(url);
      persistConfigToStorage({});
    });

    // Work Offline toggle
    offlineCheckbox.addEventListener('change', () => {
      if (offlineCheckbox.checked) {
        disconnectSocket();
        serverConfig.set({ serverFirst: false, saveLocal: true });
      } else {
        serverConfig.set({ serverFirst: true });
        connectSocket(() => {
          updateStatus();
          updateStatusLabel();
        });
      }
      updateStatus();
      updateStatusLabel();
      persistConfigToStorage({});
    });

    connectionPanel.appendChild(serverUrlLabel);
    connectionPanel.appendChild(serverUrlInput);
    connectionPanel.appendChild(statusRow);
    connectionPanel.appendChild(offlineRow);
    panels.set('connection', connectionPanel);
  }

  // --- Danger Zone: delete the tournament — tournament-specific ---
  // The one panel that keeps a colour: `panel-red` draws the danger border and header (and e2e journey 82
  // finds the delete button by it).
  if (deleteContext && inLayout('dangerZone')) {
    const { tournamentRecord, providerId, state, canDeleteOnServer, activeProvider } = deleteContext;
    const deletePanel = document.createElement('div');
    deletePanel.className = `${SETTINGS_PANEL} panel-red`;
    deletePanel.innerHTML = `<h3><i class="fa-solid fa-trash"></i> ${t('modals.settings.dangerZone')}</h3>`;

    const deleteBtn = document.createElement('button');
    deleteBtn.className = 'button is-danger is-outlined';
    deleteBtn.style.marginTop = '8px';
    deleteBtn.innerHTML = `<i class="fa-solid fa-trash" style="margin-right:6px"></i>${t('modals.tournamentActions.deleteTournament')}`;
    deleteBtn.addEventListener('click', () => {
      const tournamentId = tournamentRecord.tournamentId;
      const provId = state?.providerId || providerId;
      const navigateAway = async () => {
        tournamentEngine.reset();
        if (provId) await removeProviderTournament({ tournamentId, providerId: provId });
        context.router?.navigate(`/${TMX_TOURNAMENTS}`);
      };
      const localDelete = () => tmx2db.deleteTournament(tournamentId).then(navigateAway);

      const showServerError = (body: any) => {
        const messageKey =
          body?.errorCode === 'ERR_TOURNAMENT_NOT_ENDED'
            ? 'toasts.tournamentNotEnded'
            : body?.errorCode === 'ERR_DELETE_FORBIDDEN'
              ? 'toasts.deleteForbidden'
              : undefined;
        tmxToast({
          message: messageKey ? t(messageKey) : body?.error || t('toasts.cannotDeleteTournament'),
          intent: 'is-danger',
          pauseOnHover: true,
          duration: 6000,
        });
      };

      tmxToast({
        action: {
          onClick: async () => {
            if (!(activeProvider && provId && canDeleteOnServer)) {
              await localDelete();
              return;
            }
            let response: any;
            try {
              response = await removeTournament({ providerId: provId, tournamentId });
            } catch (err) {
              // Network/transport failure: keep local copy intact so the
              // user can retry once connectivity returns.
              console.error('[deleteTournament] server error:', err);
              tmxToast({ message: t('toasts.serverNotResponding'), intent: 'is-danger' });
              return;
            }
            // baseApi resolves to `undefined` on non-2xx (interceptor); the
            // server returns 200 with { error, errorCode } when the delete
            // is rejected. Either way, do NOT run localDelete — the user
            // needs the local copy to fix endDate or retry.
            const body = response?.data;
            if (!response || body?.error) {
              showServerError(body);
              return;
            }
            await localDelete();
          },
          text: t('common.confirm'),
        },
        message: t('modals.tournamentActions.deleteTournament'),
        intent: 'is-danger',
      });
    });

    deletePanel.appendChild(deleteBtn);
    panels.set('dangerZone', deletePanel);
  }

  for (const row of layout) {
    for (const { id, span } of row) {
      const panel = panels.get(id);
      if (!panel) continue;
      panel.style.gridColumn = `span ${span}`;
      grid.appendChild(panel);
    }
  }

  container.appendChild(grid);
}

/** Who may delete the loaded tournament; undefined when the Danger Zone is not offered. */
function resolveDeleteContext(excludeTournament?: boolean) {
  if (excludeTournament) return undefined;
  const tournamentRecord = tournamentEngine.q.tournament();
  const providerId = tournamentRecord?.parentOrganisation?.organisationId;
  const state = getLoginState();
  const superAdmin = state?.roles?.includes(SUPER_ADMIN);
  const createdByUserId = tournamentRecord?.extensions?.find((e) => e?.name === 'createdByUserId')?.value;
  const isCreator = !!createdByUserId && createdByUserId === state?.userId;
  const canDeleteOnServer = superAdmin || isCreator || state?.permissions?.includes('deleteTournament');
  const activeProvider = resolveActiveProvider(state, context.provider);

  const isProviderTournament = !!(activeProvider && providerId);
  if (!tournamentRecord || (isProviderTournament && !canDeleteOnServer)) return undefined;
  return { tournamentRecord, providerId, state, canDeleteOnServer, activeProvider };
}
