/**
 * Generate ad hoc round UI for draw structures.
 * Creates a button to trigger ad hoc round creation modal.
 */
import { isConfiguredRotatingDraw, previewRotatingRound } from 'services/rotatingPartners/roundControls';
import { addAdHocRound } from 'components/modals/addAdHocRound';

import { DRAWS_VIEW } from 'constants/tmxConstants';

export function generateAdHocRound({
  structure,
  drawId,
  callback,
}: {
  structure: any;
  drawId: string;
  callback?: () => void;
}): void {
  const generatePanel = document.createElement('div');
  generatePanel.className = 'flexcol flexcenter';
  generatePanel.style.width = '100%';
  generatePanel.style.height = '300px';

  const button = document.createElement('button');
  button.onclick = (e) => {
    e.stopPropagation();
    e.preventDefault();
    if (isConfiguredRotatingDraw(drawId)) {
      previewRotatingRound({ drawId, structure, callback });
      return;
    }
    addAdHocRound({
      newRound: true,
      structure,
      callback,
      drawId,
    });
  };
  button.className = 'button is-info';
  button.innerHTML = 'Generate round';
  generatePanel.appendChild(button);

  const drawsView = document.getElementById(DRAWS_VIEW);
  if (drawsView) drawsView.appendChild(generatePanel);
}
