/**
 * Draw form relationships and field interactions.
 * Manages form field dependencies and dynamic updates for draw creation.
 */
import { drawDefinitionConstants, tools } from 'tods-competition-factory';
import { buildSeedCountOptions, isSeedableDrawType } from './seedCount';
import { getUserTopologiesSync } from 'pages/templates/topologyBridge';
import { getChildrenByClassName } from 'services/dom/parentAndChild';
import { renderOptions, validators } from 'courthive-components';
import { removeAllChildNodes } from 'services/dom/transformers';
import { acceptedEntriesCount } from './acceptedEntriesCount';
import { DEFAULT_PLAYOFF_DRAW_TYPE } from './playoffGroups';
import { tournamentEngine } from 'services/factory/engine';
import { getTopologyTemplates } from './topologyTemplates';
import { getDrawTypeOptions } from './getDrawTypeOptions';
import { feedInQualifierCounts } from './feedInQualifying';
import { getSeedingAllowance } from './seedingPolicies';
import { drawFormModel } from './drawFormModel';

// Constants
const {
  AD_HOC,
  ADAPTIVE,
  FEED_IN,
  FEED_IN_CHAMPIONSHIP,
  LUCKY_DRAW,
  MAIN,
  PAGE_PLAYOFF,
  QUALIFYING,
  ROUND_ROBIN,
  ROUND_ROBIN_WITH_PLAYOFF,
  SWISS,
} = drawDefinitionConstants;
import {
  ADVANCE_PER_GROUP,
  AUTOMATED,
  BEST_FINISHERS,
  DRAFT,
  DRAW_MATIC,
  DRAW_NAME,
  DRAW_SIZE,
  DRAW_TYPE,
  DYNAMIC_RATINGS,
  FIC_DEPTH,
  GROUP_REMAINING,
  GROUP_SIZE,
  MANUAL,
  NONE,
  PLAYOFF_DRAW_TYPE,
  PLAYOFF_GROUP_SIZE,
  PLAYOFF_TYPE,
  QUALIFYING_FIRST,
  QUALIFYING_POSITIONS,
  QUALIFIERS_COUNT,
  RATING_SCALE,
  ROUNDS_COUNT,
  SEEDING_POLICY,
  SEEDS_COUNT,
  STRUCTURE_NAME,
  TEAM_AVOIDANCE,
  TOPOLOGY_TEMPLATE_PREFIX,
  TOP_FINISHERS,
  TOTAL_ADVANCE,
} from 'constants/tmxConstants';

/** Non-power-of-2 structure types that use raw draw size */
const NON_POW2_TYPES = new Set([
  ADAPTIVE,
  LUCKY_DRAW,
  FEED_IN,
  ROUND_ROBIN,
  ROUND_ROBIN_WITH_PLAYOFF,
  DRAW_MATIC,
  AD_HOC,
]);

/**
 * When drawType is a topology template reference, resolve the main node's
 * structureType so draw size coercion matches the actual structure.
 */
function resolveEffectiveDrawType(drawType: string): string {
  if (!drawType?.startsWith(TOPOLOGY_TEMPLATE_PREFIX)) return drawType;

  const templateName = drawType.slice(TOPOLOGY_TEMPLATE_PREFIX.length);
  const template =
    getTopologyTemplates().find((t) => t.name === templateName) ||
    getUserTopologiesSync().find((t) => t.name === templateName);

  const mainNode = template?.state?.nodes?.find((n: any) => n.stage === MAIN);
  return mainNode?.structureType || drawType;
}

interface FormRelationshipParams {
  isQualifying?: boolean;
  isPopulateMain?: boolean;
  maxQualifiers?: number;
  drawId?: string;
  event: any;
}

interface FormInteractionParams {
  fields?: Record<string, HTMLElement>;
  inputs: Record<string, any>;
  drawType?: string;
  drawId?: string;
  stage?: string;
  name?: string;
  event?: any;
  e?: Event;
}

/**
 * Display of the round-robin group and playoff fields, all of which key off the same two values.
 * Extracted from `updateFieldVisibility` to keep that function under the cognitive-complexity
 * threshold — it is a cohesive block, not an arbitrary slice.
 */
function updateGroupFieldVisibility(
  fields: Record<string, HTMLElement>,
  drawType: string,
  inputs: Record<string, any>,
) {
  const isRRPlayoff = drawType === ROUND_ROBIN_WITH_PLAYOFF;
  const playoffType = inputs[PLAYOFF_TYPE].value;
  const playoffDrawType = inputs[PLAYOFF_DRAW_TYPE]?.value;
  const advancesByFinishers = playoffType === TOP_FINISHERS || playoffType === BEST_FINISHERS;

  fields[ADVANCE_PER_GROUP].style.display = isRRPlayoff && playoffType === TOP_FINISHERS ? '' : NONE;
  fields[TOTAL_ADVANCE].style.display = isRRPlayoff && playoffType === BEST_FINISHERS ? '' : NONE;
  fields[GROUP_REMAINING].style.display = isRRPlayoff && advancesByFinishers ? '' : NONE;
  fields[PLAYOFF_TYPE].style.display = isRRPlayoff ? '' : NONE;
  fields[PLAYOFF_DRAW_TYPE].style.display = isRRPlayoff ? '' : NONE;
  fields[PLAYOFF_GROUP_SIZE].style.display = isRRPlayoff && playoffDrawType === ROUND_ROBIN ? '' : NONE;
  fields[GROUP_SIZE].style.display = ([ROUND_ROBIN, ROUND_ROBIN_WITH_PLAYOFF] as string[]).includes(drawType)
    ? ''
    : NONE;
}

export function getDrawFormRelationships({
  isQualifying,
  isPopulateMain,
  maxQualifiers,
  drawId,
  event,
}: FormRelationshipParams): any[] {
  const stage = isQualifying ? QUALIFYING : MAIN;

  // set when checkCreationMethod, not the operator, moved Creation to Manual
  let forcedManual = false;
  // a draw size the user typed outlives draw type and qualifier changes while it holds the entries and qualifiers:
  // a draw can be generated before its entries, at any size (CA, 2026-10-09)
  let typedDrawSize: number | undefined;
  const checkCreationMethod = ({ fields, inputs }: FormInteractionParams) => {
    const drawSizeValue = inputs[DRAW_SIZE].value || 0;
    const drawSize = validators.numericValidator(drawSizeValue) ? Number.parseInt(drawSizeValue) : 0;
    const isQualifyingFirst = inputs[QUALIFYING_FIRST]?.checked;
    const effectiveStage = isQualifyingFirst ? QUALIFYING : stage;
    const entriesCount = acceptedEntriesCount({ drawId, event, stage: effectiveStage });
    const qualifiersValue = inputs['qualifiersCount'].value || 0;
    const qualifiersCount = validators.numericValidator(qualifiersValue) ? Number.parseInt(qualifiersValue) : 0;
    const effectiveIsQualifying = isQualifying || isQualifyingFirst;
    const manualOnly = effectiveIsQualifying
      ? maxQualifiers || drawSize < entriesCount
      : maxQualifiers || drawSize < entriesCount + qualifiersCount;
    // select the Manual OPTION: its value is `false`, so assigning the label matched no option and blanked the field.
    // The check runs per keystroke ("22" passes through "2"), so a Manual the form forced is undone once allowed.
    const creation = inputs[AUTOMATED];
    const manualOption = [...(creation.options ?? [])].find((option: any) => option.label === MANUAL);
    if (manualOnly && manualOption && creation.value !== manualOption.value) {
      creation.value = manualOption.value;
      forcedManual = true;
    } else if (!manualOnly && forcedManual) {
      creation.value = AUTOMATED;
      forcedManual = false;
    }
    const help = fields && getChildrenByClassName(fields[AUTOMATED], 'help')?.[0];
    if (help) help.style.display = manualOnly ? '' : NONE;
    for (const option of inputs[AUTOMATED].options) {
      if (option.label === AUTOMATED) {
        option.disabled = manualOnly;
      }
    }
  };

  /** Entries that will actually contend for the new draw's stage — the cap on how deep seeding can go. */
  const seedableEntriesCount = (inputs: Record<string, any>): number => {
    const effectiveStage = inputs?.[QUALIFYING_FIRST]?.checked ? QUALIFYING : stage;
    return acceptedEntriesCount({ drawId, event, stage: effectiveStage });
  };

  const updateSeedCountOptions = ({
    inputs,
    drawSize,
    drawType,
  }: {
    inputs: Record<string, any>;
    drawSize: number;
    drawType?: string;
  }) => {
    const select = inputs[SEEDS_COUNT];
    if (!select) return;

    const currentValue = select.value;
    const participantsCount = seedableEntriesCount(inputs);
    const options = buildSeedCountOptions({
      ...getSeedingAllowance({
        selectedSeedingPolicy: inputs[SEEDING_POLICY]?.value,
        eventId: event?.eventId,
        participantsCount,
        drawSize,
      }),
      drawType: drawType ?? inputs[DRAW_TYPE]?.value,
      groupSize: inputs[GROUP_SIZE]?.value,
      participantsCount,
      drawSize,
    });
    const selectedValue = options.some((option) => String(option.value) === String(currentValue)) ? currentValue : '';
    removeAllChildNodes(select);
    renderOptions(select, { options, value: selectedValue });
  };

  const updateDrawSize = ({ drawType, drawId, fields, inputs }: FormInteractionParams): number => {
    const isQualifyingFirst = inputs?.[QUALIFYING_FIRST]?.checked;
    const effectiveStage = isQualifyingFirst ? QUALIFYING : stage;
    const effectiveIsQualifying = isQualifying || isQualifyingFirst;
    const entriesCount = maxQualifiers
      ? inputs[DRAW_SIZE].value
      : acceptedEntriesCount({ drawId, event, stage: effectiveStage });
    const qualifiersValue = inputs['qualifiersCount'].value || 0;
    const qualifiersCount =
      (validators.numericValidator(qualifiersValue) && Number.parseInt(qualifiersValue)) || (maxQualifiers ? 1 : 0);
    const drawSizeInteger =
      effectiveIsQualifying && !maxQualifiers ? entriesCount : Number.parseInt(entriesCount) + qualifiersCount;
    const effectiveType = resolveEffectiveDrawType(drawType as string);
    const derivedDrawSize =
      ((maxQualifiers || NON_POW2_TYPES.has(effectiveType)) && drawSizeInteger) || tools.nextPowerOf2(drawSizeInteger);
    const keepTyped = !maxQualifiers && typedDrawSize !== undefined && typedDrawSize >= Number(drawSizeInteger);
    const drawSize = keepTyped ? (typedDrawSize as number) : derivedDrawSize;
    inputs[DRAW_SIZE].value = drawSize;

    updateSeedCountOptions({ inputs, drawSize, drawType });

    checkCreationMethod({ fields, inputs });
    return drawSize;
  };

  const qualifiersCountChange = ({ fields, inputs }: FormInteractionParams) => {
    let drawSize = Number.parseInt(inputs[DRAW_SIZE].value);
    const enteredValue = inputs['qualifiersCount'].value;
    if (validators.numericValidator(enteredValue) && Number.parseInt(enteredValue) < 1) {
      inputs['qualifiersCount'].value = maxQualifiers ? 1 : 0;
    }
    const generateButton = document.getElementById('generateDraw') as HTMLButtonElement;
    let qualifiersValue = inputs['qualifiersCount'].value;
    if (generateButton) generateButton.disabled = false;

    if (
      maxQualifiers &&
      validators.numericValidator(qualifiersValue) &&
      Number.parseInt(qualifiersValue) > maxQualifiers
    ) {
      inputs['qualifiersCount'].value = maxQualifiers;
    } else if (!maxQualifiers) {
      const drawType = inputs[DRAW_TYPE].value;
      drawSize = updateDrawSize({ drawId, drawType, fields, inputs });
    }

    qualifiersValue = inputs['qualifiersCount'].value;
    if (
      generateButton &&
      (!validators.numericValidator(qualifiersValue) || drawSize <= Number.parseInt(qualifiersValue))
    ) {
      generateButton.disabled = true;
    }
  };

  const updateFicDepthOptions = (inputs: Record<string, any>) => {
    const drawSize = Number.parseInt(inputs[DRAW_SIZE]?.value) || 0;
    for (const option of inputs[FIC_DEPTH]?.options ?? []) {
      if (option.value === 'R16') option.disabled = drawSize <= 16;
      if (option.value === 'QF') option.disabled = drawSize <= 8;
      if (option.value === 'SF') option.disabled = drawSize <= 4;
    }
  };

  const updateFieldVisibility = (
    fields: Record<string, HTMLElement>,
    drawType: string,
    inputs: Record<string, any>,
  ) => {
    const isDrawMatic = drawType === DRAW_MATIC;
    // Deliberately NOT named `isAdHocType`: the factory has a function of that name whose
    // membership is different — `{AD_HOC, LADDER, SWISS}`, no DRAW_MATIC — and 7.0.0's migration
    // guide talks about it, so a shadow here sends a reader to the wrong definition. The factory's
    // is also not exported from the package (neither is `isLadder`), so it cannot be imported even
    // where the semantics would match. This predicate is TMX's own: which draw types hide the
    // seeding-policy and qualifiers fields on this form.
    const hidesSeedingFields = drawType === AD_HOC || drawType === SWISS || isDrawMatic;
    const isFIC = drawType === FEED_IN_CHAMPIONSHIP;

    updateGroupFieldVisibility(fields, drawType, inputs);

    const isSwiss = drawType === SWISS;
    fields[ROUNDS_COUNT].style.display = isDrawMatic ? '' : NONE;
    fields[RATING_SCALE].style.display = isDrawMatic || isSwiss ? '' : NONE;
    fields[DYNAMIC_RATINGS].style.display = isDrawMatic ? '' : NONE;
    fields[TEAM_AVOIDANCE].style.display = isDrawMatic ? '' : NONE;

    if (isFIC) updateFicDepthOptions(inputs);
    fields[FIC_DEPTH].style.display = isFIC ? '' : NONE;

    fields[AUTOMATED].style.display = drawType === SWISS ? NONE : '';
    fields[SEEDING_POLICY].style.display = hidesSeedingFields ? NONE : '';
    // Not the same predicate as the seeding policy above: LUCKY_DRAW and ADAPTIVE are not ad hoc,
    // but the factory forces their seedsCount to 0, so offering a count would be a lie.
    fields[SEEDS_COUNT].style.display = isSeedableDrawType(drawType) ? '' : NONE;
    fields[QUALIFIERS_COUNT].style.display = hidesSeedingFields && !isSwiss ? NONE : '';

    // DRAFT positioning doesn't apply to DrawMatic or Swiss — both generate
    // pairings algorithmically per round rather than from a pre-positioned
    // bracket. Hide the option and snap any pre-existing DRAFT selection
    // back to AUTOMATED so submit doesn't go down the draft path.
    const automatedInput = inputs[AUTOMATED];
    if (automatedInput?.options) {
      const hideDraft = isDrawMatic || isSwiss;
      for (const option of automatedInput.options) {
        if (option.value === DRAFT) option.hidden = hideDraft;
      }
      if (hideDraft && automatedInput.value === DRAFT) automatedInput.value = AUTOMATED;
    }
  };

  /** A FEED_IN qualifying produces only qualifier counts that divide its size twice over (13 positions: 1).
   *  Moves an impossible count to the largest possible one below it, within the target's capacity. */
  const fitFeedInQualifiers = (inputs: Record<string, any>) => {
    const isQualifyingFirst = inputs[QUALIFYING_FIRST]?.checked;
    if (inputs[DRAW_TYPE]?.value !== FEED_IN || !(isQualifying || isQualifyingFirst)) return;
    const drawSize = Number.parseInt(inputs[DRAW_SIZE].value);
    const counts = (validators.numericValidator(inputs[DRAW_SIZE].value) && feedInQualifierCounts(drawSize)) || [];
    const input = inputs[isQualifyingFirst ? QUALIFYING_POSITIONS : QUALIFIERS_COUNT];
    const current = Number.parseInt(input?.value);
    const allowed = counts.filter((count) => !maxQualifiers || count <= maxQualifiers);
    if (!input || !allowed.length || allowed.includes(current)) return;
    input.value = allowed.filter((count) => count <= current).pop() ?? allowed[0];
  };

  const drawTypeChange = ({ e, fields, inputs }: FormInteractionParams) => {
    const drawType = (e!.target as HTMLSelectElement).value;

    if (!maxQualifiers) updateDrawSize({ drawId, drawType, fields, inputs });
    fitFeedInQualifiers(inputs);
    checkCreationMethod({ fields, inputs });

    if (fields) {
      updateFieldVisibility(fields, drawType, inputs);
    }
  };

  const drawSizeChange = ({ fields, inputs }: FormInteractionParams) => {
    const generateButton = document.getElementById('generateDraw') as HTMLButtonElement;
    const drawSizeValue = inputs[DRAW_SIZE].value || 0;
    const drawSize = validators.numericValidator(drawSizeValue) ? Number.parseInt(drawSizeValue) : 0;
    typedDrawSize = drawSize || undefined;
    const entriesCount = acceptedEntriesCount({ drawId, event, stage });
    const maxDrawSize = Math.max(tools.nextPowerOf2(entriesCount), 512);
    const valid = validators.numericRange(2, maxDrawSize)(drawSizeValue);
    if (generateButton) generateButton.disabled = !valid;
    const { validGroupSizes = [] } = tournamentEngine.getValidGroupSizes({ drawSize, groupSizeLimit: 8 });
    const options = validGroupSizes.map((size: number) => ({ label: size, value: size }));
    const groupSizeSelect = inputs[GROUP_SIZE];
    const value = validGroupSizes.includes(drawSize) ? 4 : validGroupSizes[0];
    removeAllChildNodes(groupSizeSelect);
    renderOptions(groupSizeSelect, { options, value });
    updateSeedCountOptions({ inputs, drawSize });
    fitFeedInQualifiers(inputs);
    checkCreationMethod({ fields, inputs });
  };

  const playoffDrawTypeChange = ({ e, fields, inputs }: FormInteractionParams) => {
    const playoffDrawType = (e!.target as HTMLSelectElement).value;
    if (fields) {
      fields[PLAYOFF_GROUP_SIZE].style.display = playoffDrawType === ROUND_ROBIN ? '' : NONE;

      // PAGE_PLAYOFF requires exactly 4 finishers — force TOP_FINISHERS with advance=2
      if (playoffDrawType === PAGE_PLAYOFF && inputs) {
        inputs[PLAYOFF_TYPE].value = TOP_FINISHERS;
        inputs[ADVANCE_PER_GROUP].value = '2';
        fields[ADVANCE_PER_GROUP].style.display = '';
        fields[GROUP_REMAINING].style.display = '';
        fields[TOTAL_ADVANCE].style.display = NONE;
      }
    }
  };

  const playoffTypeChange = ({ e, fields, inputs }: FormInteractionParams) => {
    const playoffType = (e!.target as HTMLSelectElement).value;
    if (fields) {
      fields[ADVANCE_PER_GROUP].style.display = playoffType === TOP_FINISHERS ? '' : NONE;
      fields[TOTAL_ADVANCE].style.display = playoffType === BEST_FINISHERS ? '' : NONE;
      fields[GROUP_REMAINING].style.display =
        playoffType === TOP_FINISHERS || playoffType === BEST_FINISHERS ? '' : NONE;

      // PAGE_PLAYOFF requires TOP_FINISHERS; reset if user changes away
      if (playoffType !== TOP_FINISHERS && inputs?.[PLAYOFF_DRAW_TYPE]?.value === PAGE_PLAYOFF) {
        inputs[PLAYOFF_DRAW_TYPE].value = DEFAULT_PLAYOFF_DRAW_TYPE;
        fields[PLAYOFF_GROUP_SIZE].style.display = NONE;
      }
    }
  };

  const advancePerGroupChange = ({ e, fields, inputs }: FormInteractionParams) => {
    const advancePerGroup = Number.parseInt((e!.target as HTMLSelectElement).value);
    // PAGE_PLAYOFF requires exactly 2 per group; reset if user changes away
    if (advancePerGroup !== 2 && inputs?.[PLAYOFF_DRAW_TYPE]?.value === PAGE_PLAYOFF && fields) {
      inputs[PLAYOFF_DRAW_TYPE].value = DEFAULT_PLAYOFF_DRAW_TYPE;
      fields[PLAYOFF_GROUP_SIZE].style.display = NONE;
    }
  };

  const groupSizeChange = ({ inputs }: FormInteractionParams) => {
    const newGroupSize = Number.parseInt(inputs[GROUP_SIZE].value);
    const existingOptions = inputs[ADVANCE_PER_GROUP].options;
    const existingValues = Array.from(existingOptions).map((o: any) => Number.parseInt(o.value));
    const maxValue = Math.max(...existingValues);
    if (maxValue > newGroupSize) {
      tools
        .generateRange(newGroupSize + 1, maxValue + 1)
        .reverse()
        .forEach((v) => {
          inputs[ADVANCE_PER_GROUP].remove(v - 2);
        });
    } else if (maxValue < newGroupSize) {
      tools
        .generateRange(maxValue + 1, newGroupSize + 1)
        .forEach((v) => inputs[ADVANCE_PER_GROUP].add(new Option(v.toString(), v.toString())));
    }

    // Round robin seeds one participant per group before it seeds a second, so the group size
    // changes which seed counts are reachable.
    updateSeedCountOptions({ inputs, drawSize: Number.parseInt(inputs[DRAW_SIZE].value) || 0 });
  };

  const structureNameChange = ({ inputs, name }: FormInteractionParams) => {
    const newStructureName = inputs[name!].value;
    const generateButton = document.getElementById('generateDraw') as HTMLButtonElement;
    const valid = validators.nameValidator(4)(newStructureName);
    if (generateButton) generateButton.disabled = !valid;
  };

  const setOptionalFieldDisplay = (fields: Record<string, HTMLElement>, fieldName: string, display: string) => {
    const field = fields[fieldName];
    if (field) field.style.display = display;
  };

  const qualifyingFirstChange = ({ fields, inputs }: FormInteractionParams) => {
    const checked = inputs[QUALIFYING_FIRST]?.checked;
    if (fields) {
      setOptionalFieldDisplay(fields, DRAW_NAME, checked ? NONE : '');
      setOptionalFieldDisplay(fields, STRUCTURE_NAME, checked ? '' : NONE);
      setOptionalFieldDisplay(fields, QUALIFIERS_COUNT, checked ? NONE : '');
      setOptionalFieldDisplay(fields, QUALIFYING_POSITIONS, checked ? '' : NONE);
      setOptionalFieldDisplay(fields, SEEDING_POLICY, checked ? NONE : '');
      setOptionalFieldDisplay(fields, SEEDS_COUNT, checked ? NONE : '');
    }

    // Update draw type options to qualifying-appropriate subset
    const drawTypeSelect = inputs[DRAW_TYPE];
    const currentDrawType = drawTypeSelect.value;
    removeAllChildNodes(drawTypeSelect);
    renderOptions(drawTypeSelect, { options: getDrawTypeOptions({ isQualifying: checked }) });
    // Restore previous value if still available, otherwise default to first option
    const hasOption = Array.from(drawTypeSelect.options).some((o: any) => o.value === currentDrawType);
    if (hasOption) drawTypeSelect.value = currentDrawType;

    // Re-derive draw size via the state-engine model (Phase B mode 5/6).
    // The model uses STRUCTURE_SELECTED_STATUSES (factory canonical) for
    // entry counting — not the drifted TMX helper.
    const toggleMode = checked
      ? ({ kind: 'NEW_MAIN_WITH_QUALIFYING_FIRST', event } as const)
      : ({ kind: 'NEW_MAIN', event } as const);
    const toggleView = drawFormModel(toggleMode, {});
    // the size field now sizes the other structure: a size typed for the one before does not carry over
    typedDrawSize = undefined;
    inputs[DRAW_SIZE].value = toggleView.derivedValues.drawSize;
    updateSeedCountOptions({ inputs, drawSize: toggleView.derivedValues.drawSize });
    fitFeedInQualifiers(inputs);

    checkCreationMethod({ fields, inputs });
  };

  return [
    {
      onInput: ({ inputs }: FormInteractionParams) => structureNameChange({ inputs, name: DRAW_NAME }),
      control: DRAW_NAME,
    },
    {
      onInput: ({ inputs }: FormInteractionParams) => structureNameChange({ inputs, name: STRUCTURE_NAME }),
      control: STRUCTURE_NAME,
    },
    {
      onChange: groupSizeChange,
      control: GROUP_SIZE,
    },
    {
      onChange: drawTypeChange,
      control: DRAW_TYPE,
    },
    {
      onChange: playoffTypeChange,
      control: PLAYOFF_TYPE,
    },
    {
      onChange: playoffDrawTypeChange,
      control: PLAYOFF_DRAW_TYPE,
    },
    {
      onChange: advancePerGroupChange,
      control: ADVANCE_PER_GROUP,
    },
    {
      onInput: drawSizeChange,
      control: DRAW_SIZE,
    },
    {
      onInput: qualifiersCountChange,
      control: QUALIFIERS_COUNT,
    },
    // QUALIFYING_FIRST checkbox only exists when not isQualifying, not isPopulateMain, and no existing drawId
    ...(!isQualifying && !isPopulateMain && !drawId
      ? [
          {
            onChange: qualifyingFirstChange,
            control: QUALIFYING_FIRST,
          },
        ]
      : []),
  ];
}
